INSERT INTO chat_message (id, room_id, sender_id, parent_id, message_text, created_at) VALUES
    ('11000000-0000-4000-8000-000000000001', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000006', NULL, 'Ne felejtsétek el kitölteni az időnyilvántartást a hét végéig.', '2026-03-04 10:00:00'),
    ('11000000-0000-4000-8000-000000000002', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000003', NULL, 'Írtam nekik, a héten választ várunk.', '2026-03-15 13:32:02'),
    ('11000000-0000-4000-8000-000000000003', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000007', '11000000-0000-4000-8000-000000000002', 'Egyetértek.', '2026-03-22 22:45:47'),
    ('11000000-0000-4000-8000-000000000004', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000005', NULL, 'A prezentációhoz még hiányzik két dia, ki vállalja?', '2026-03-27 06:57:49'),
    ('11000000-0000-4000-8000-000000000005', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000002', NULL, 'Nem érkezett még visszajelzés az ügyféltől, ránézne valaki?', '2026-04-09 07:06:08'),
    ('11000000-0000-4000-8000-000000000006', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000004', '11000000-0000-4000-8000-000000000003', 'Oké, jelzek, ha elkészültem.', '2026-04-20 20:32:20'),
    ('11000000-0000-4000-8000-000000000007', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000003', NULL, 'Elkészültem a feladattal, kérlek nézzétek át.', '2026-04-30 08:28:23'),
    ('11000000-0000-4000-8000-000000000008', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000004', NULL, 'Jó reggelt mindenkinek! Ma a hibajavításokra koncentrálnék.', '2026-05-08 15:51:54'),
    ('11000000-0000-4000-8000-000000000009', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000004', '11000000-0000-4000-8000-000000000008', 'Egyetértek.', '2026-05-20 06:07:50'),
    ('11000000-0000-4000-8000-000000000010', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000008', NULL, 'Köszi, akkor mehet a merge.', '2026-05-31 08:37:03'),
    ('11000000-0000-4000-8000-000000000011', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000007', NULL, 'Ott leszek, csak egy dolgot még le kell zárnom reggel.', '2026-06-04 20:26:35'),
    ('11000000-0000-4000-8000-000000000012', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000008', '11000000-0000-4000-8000-000000000002', 'Oké, jelzek, ha elkészültem.', '2026-06-17 08:14:21'),
    ('11000000-0000-4000-8000-000000000013', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000008', '11000000-0000-4000-8000-000000000003', 'Köszi, ezt megnézem.', '2026-06-24 04:14:34'),
    ('11000000-0000-4000-8000-000000000014', '0e000000-0000-4000-8000-000000000001', '01000000-0000-4000-8000-000000000003', NULL, 'Megnéztem a hibajegyet, reprodukálható, kijavítom ma.', '2026-06-28 04:42:19'),
